import { Component, inject, signal, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';
import { UserService } from '../../../../../services/user.service';
import { User, UserRole, roleLabel } from '../../../../../models/user.model';
import { PaginatorComponent } from '../../../../../shared/components/paginator/paginator.component';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';

@Component({
  selector: 'app-usuario-list',
  standalone: true,
  imports: [PaginatorComponent, DatePipe],
  templateUrl: './usuario-list.component.html',
})
export class UsuarioListComponent implements OnInit {
  private readonly userService = inject(UserService);
  private readonly router = inject(Router);
  protected readonly searchTerm = signal('');
  protected readonly selectedRole = signal<UserRole | ''>('');
  protected readonly page = signal(1);
  protected readonly perPage = signal(15);
  protected readonly users = signal<User[]>([]);
  protected readonly total = signal(0);
  protected readonly lastPage = signal(1);
  protected readonly loading = signal(false);
  protected readonly errorMessage = signal('');
  protected readonly successMessage = signal('');
  protected readonly roleLabel = roleLabel;

  ngOnInit(): void {
    this.loadUsers();
  }

  protected loadUsers(): void {
    this.loading.set(true);
    this.errorMessage.set('');

    this.userService
      .getUsers({
        search: this.searchTerm() || undefined,
        role: (this.selectedRole() || undefined) as UserRole | undefined,
        page: this.page(),
        perPage: this.perPage(),
      })
      .subscribe({
        next: (res) => {
          this.users.set(res.users);
          this.total.set(res.total);
          this.lastPage.set(res.lastPage);
          this.loading.set(false);
        },
        error: (err) => {
          this.errorMessage.set(extractErrorMessage(err));
          this.loading.set(false);
        },
      });
  }

  protected onSearch(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this.searchTerm.set(value);
    this.page.set(1);
    this.loadUsers();
  }

  protected onRoleFilter(event: Event): void {
    const value = (event.target as HTMLSelectElement).value as UserRole | '';
    this.selectedRole.set(value);
    this.page.set(1);
    this.loadUsers();
  }

  protected onPageChange(newPage: number): void {
    this.page.set(newPage);
    this.loadUsers();
  }

  protected navigateToNuevo(): void {
    this.router.navigate(['/ejecutivos/configuracion/usuarios/nuevo']);
  }

  protected navigateToEditar(user: User): void {
    this.router.navigate(['/ejecutivos/configuracion/usuarios', user.id, 'editar']);
  }

  protected deleteUser(user: User): void {
    if (!confirm(`¿Estás seguro de eliminar al usuario ${user.name}?`)) {
      return;
    }

    this.userService.deleteUser(user.id).subscribe({
      next: () => {
        this.successMessage.set('Usuario eliminado correctamente.');
        this.loadUsers();
      },
      error: (err) => {
        this.errorMessage.set(extractErrorMessage(err));
      },
    });
  }
}
